+            || nodeScope != excludeScope
+            && surroundingScope != excludeScope)
+            && nodeScope.isIn(scope)
+            && surroundingScope.isIn(scope)
+            && includePattern.matcher(outerTypeName).find()
+            && ignorePattern.matcher(outerTypeName).find() == false;
+    }
